-- ----------------------------
-- Table structure for calculation_algorithm
-- ----------------------------
DROP TABLE IF EXISTS `calculation_algorithm`;
CREATE TABLE `calculation_algorithm`  (
  `FC_ID` int NOT NULL,
  `TITLE` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '标题',
