-- ----------------------------
DROP TABLE IF EXISTS `t_rtu_baseinfo`;
CREATE TABLE `t_rtu_baseinfo`  (
  `RTUCD` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'RTU编码',
  `STCD` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '测站编码',
  `STNM` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '测站名称',
  `BDATE` date NULL DEFAULT NULL COMMENT '新建日期',
  `LGTD` decimal(10, 6) NULL DEFAULT NULL COMMENT '经度',
  `LTTD` decimal(10, 6) NULL DEFAULT NULL COMMENT '纬度',
  `STLC` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '站址',
  `WARN_VAL` decimal(3, 1) NULL DEFAULT NULL COMMENT '通讯预警值，单位小时，多少小时没有报讯，则认为通讯异常',
  `LATEST_TM` datetime NULL DEFAULT NULL COMMENT '最近通讯时间',
  `ONLINE` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '设备是否在线',
  `REMARK` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`RTUCD`) USING BTREE,
  UNIQUE INDEX `STCD`(`STCD` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_rtu_baseinfo
-- ----------------------------

