-- ----------------------------
-- Table structure for t_rtu_status_warn
-- ----------------------------
DROP TABLE IF EXISTS `t_rtu_status_warn`;
CREATE TABLE `t_rtu_status_warn`  (
  `RTUCD` varchar(30) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'RTU编码',
  `TM` datetime NOT NULL COMMENT '时间',
  `JLDCDZT` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '交流电充电状态 0：正常；1：停电(告警)',
  `XDCDYZT` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '蓄电池电压状态  0：正常；1：电压低',
  `SWCXZT` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '水位超限报警状态  0：正常；1：报警',
  `LLCXZT` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '流量超限报警状态 0：正常；1：报警',
  `SZCXZT` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '水质超限报警状态   0：正常；1：报警',
  `LLYBZT` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '流量仪表状态   0：正常；1：故障',
  `SWYBZT` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '水位仪表状态   0：正常；1：故障',
  `ZDXMZT` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '终端箱门状态  0：开启；1：关闭',
  `CCQZT` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '存储器状态  0：正常；1：异常',
  `ICKGNYX` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT 'IC 卡功能有效 0：关闭；1：IC 卡有效',
  `SBGZZT` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '水泵工作状态   0：水泵工作；1：水泵停机',
  `SYSLBJ` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '剩余水量报警  0：未超限；1：水量超限',
  `SBKTZT` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '水泵开停状态',
  `SYCXBJ` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '水压超限报警',
  `ZDICKBJ` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '终端 IC 卡功能报警',
  `DZKZBJ` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '定值控制报警',
  `DZKZSFTR` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '定值控制是否投入。0：退出；1：投入；',
  `DYGZZT` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '电源工作状态。0：AC220V 供电；1：蓄电池供电',
  `ZDXMZTBJ` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '终端箱门状态报警',
  `ZDGZMS` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '终端工作模式',
  PRIMARY KEY (`TM`, `RTUCD`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci COMMENT = '遥测终端状态和报警状态' ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of t_rtu_status_warn
-- ----------------------------

