-- ----------------------------
-- Table structure for wq_awqmd_d
-- ----------------------------
DROP TABLE IF EXISTS `wq_awqmd_d`;
CREATE TABLE `wq_awqmd_d`  (
  `STCD` varchar(16) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL,
  `TM` datetime NOT NULL,
  `WT` decimal(3, 1) NULL DEFAULT NULL COMMENT '水温',
  `PH` decimal(4, 2) NULL DEFAULT NULL COMMENT 'PH值',
  `COND` decimal(6, 0) NULL DEFAULT NULL COMMENT '电导率',
  `TURB` decimal(6, 3) NULL DEFAULT NULL COMMENT '浊度',
  `DOX` decimal(4, 2) NULL DEFAULT NULL COMMENT '溶解氧',
  `CODMN` decimal(6, 1) NULL DEFAULT NULL COMMENT '高锰酸盐指数',
  `CODCR` decimal(7, 1) NULL DEFAULT NULL COMMENT '化学需氧量',
  `TN` decimal(5, 2) NULL DEFAULT NULL COMMENT '总氮',
  `NH3N` decimal(6, 2) NULL DEFAULT NULL COMMENT '氨氮',
  `NO2` decimal(5, 3) NULL DEFAULT NULL COMMENT '亚硝酸盐氮',
  `NO3` decimal(5, 2) NULL DEFAULT NULL COMMENT '硝酸盐氮',
  `TP` decimal(5, 3) NULL DEFAULT NULL COMMENT '总磷',
  `TOC` decimal(4, 1) NULL DEFAULT NULL COMMENT '总有机碳',
  `VLPH` decimal(5, 3) NULL DEFAULT NULL COMMENT '挥发性酚',
  `CHLA` decimal(6, 3) NULL DEFAULT NULL COMMENT '叶绿素a',
