  `CR6` decimal(5, 3) NULL DEFAULT NULL COMMENT '六价铬',
  `CU` decimal(7, 4) NULL DEFAULT NULL COMMENT '铜',
  `PB` decimal(7, 5) NULL DEFAULT NULL COMMENT '铅',
  `CD` decimal(7, 5) NULL DEFAULT NULL COMMENT '镉',
  `ZN` decimal(6, 4) NULL DEFAULT NULL COMMENT '锌',
  `SB` decimal(7, 5) NULL DEFAULT NULL COMMENT '锑',
  `REDOX` decimal(5, 1) NULL DEFAULT NULL COMMENT '氧化还原电位',
  `BOD5` decimal(5, 1) NULL DEFAULT NULL COMMENT '五日生化需氧量',
  `SE` decimal(7, 5) NULL DEFAULT NULL COMMENT '硒',
  `CN` decimal(5, 3) NULL DEFAULT NULL COMMENT '氰化物',
  `S2` decimal(5, 2) NULL DEFAULT NULL COMMENT '硫化物',
  `FCG` decimal(10, 0) NULL DEFAULT NULL COMMENT '粪大肠菌群',
  `SO4` decimal(7, 2) NULL DEFAULT NULL COMMENT '硫酸盐',
  `CL` decimal(7, 2) NULL DEFAULT NULL COMMENT '氯化物',
  `FE` decimal(4, 2) NULL DEFAULT NULL COMMENT '铁',
  `MN` decimal(4, 2) NULL DEFAULT NULL COMMENT '锰',
  `OIL` decimal(6, 3) NULL DEFAULT NULL COMMENT '石油类',
  `LAS` decimal(6, 3) NULL DEFAULT NULL COMMENT '阴离子表面活性剂',
  `BHC` decimal(7, 6) NULL DEFAULT NULL COMMENT '六六六',
  `DDT` decimal(7, 6) NULL DEFAULT NULL COMMENT '滴滴涕',
  `BENF` decimal(5, 2) NULL DEFAULT NULL COMMENT '苯酚',
  `OP` decimal(7, 6) NULL DEFAULT NULL COMMENT '有机氯农药',
  `TOXIC` decimal(4, 2) NULL DEFAULT NULL COMMENT '生物毒性',
  PRIMARY KEY (`TM`, `STCD`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = DYNAMIC;

