-- ----------------------------
DROP TABLE IF EXISTS `wr_rtu_b`;
CREATE TABLE `wr_rtu_b`  (
  `RTU_CD` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'RTU代码',
  `ORG_CD` varchar(9) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '生产厂商的组织机构代码',
  `PROD_SN` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'RTU主机设备出厂编号',
  `DEV_SN` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '合同规定的设备型号',
  `ENCR_SN` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '加密狗的产品编号',
  `POWER` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '填写RTU的工作电源类型代码',
  `PROD_DT` datetime NULL DEFAULT NULL COMMENT 'RTU出厂日期',
  `OUT_DATA_MODE` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '输出数据格式',
  `SECR_MOD` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '测站是否是加密模块。布尔型，1代表有加密模块，0代表没有',
  `TS` longblob NULL COMMENT '时间戳',
  `NT` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '备注',
  `STCD` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `STNM` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '测站名称',
  `SIM_SN` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT 'SIM卡编号',
  `RTU_BRAND` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT 'RTU品牌',
  `STLC` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '安装位置',
  `LGTD` decimal(10, 7) NULL DEFAULT NULL COMMENT '安装位置经度',
  `LTTD` decimal(10, 7) NULL DEFAULT NULL COMMENT '安装位置纬度',
  PRIMARY KEY (`RTU_CD`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wr_rtu_b
-- ----------------------------

-- ----------------------------
-- Table structure for wr_rtu_b_exp
-- ----------------------------
DROP TABLE IF EXISTS `wr_rtu_b_exp`;
CREATE TABLE `wr_rtu_b_exp`  (
  `RTU_CD` char(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'RTU代码（RTU）',
  `RTU_NAME` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'RTU名称（RTU）',
  `STCD` varchar(128) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '采集站点（RTU）\r\n   一个RTU可能采集多个站点数据，多个站点数据使用逗号,分隔',
  `RTU_HARDVER` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '硬件版本（RTU）',
  `RTU_SOFTVER` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '软件版本（RTU）',
  `RTU_TYPE` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '设备类型（RTU）\r\n   存储 RTU80,RTU90等值',
  `RTU_INST_ADDRESS` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '安装位置（RTU）',
  `POWER_POSITION` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '电源信息-接入地点（电源信息）',
  `POWER_VOLUME` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '电源信息-容量（电源信息）',
  `POWER_VOL` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '电源信息-电压等级（电源信息）',
  `POWER_FACTORY` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '电源信息-厂家（电源信息）',
  `NET_FACTORY` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '通信设备信息-厂家（通信设备信息）',
  `NET_TM` datetime NULL DEFAULT NULL COMMENT '电源信息-出厂日期',
  `NET_VOL` varchar(64) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '电源信息-供电电压',
  `NET_CONTROLLED` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '电源信息-电源是否受控\r\n   1：受控\r\n   0：未受控',
  `NET_SIM` varchar(16) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '通信设备信息-SIM号（通信设备信息）',
  `LGTD` decimal(10, 6) NULL DEFAULT NULL COMMENT '经度（RTU）',
  `LTTD` decimal(10, 6) NULL DEFAULT NULL COMMENT '纬度（RTU）',
  `CONNECTED` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '保持连接\r\n   \r\n   完成传输后是否断开连接\r\n   1：是（压力小时可以设置为1，始终保持连接）\r\n   0：否（压力大时可以设置0、提高并发）\r\n   \r\n   \r\n   一般情况下完成数据报送后都应该断开连接（提高并发性能）\r\n   但一些模块需要在保持连接情况下进行操作。\r\n   比如：RTU升级、召测、RTU调试等功能，\r\n   \r\n   因此如果在做这些操作前应该调整这个状态为1，等待连接后再进行操作。\r\n   \r\n   对于开关闸这种时效性非常高的测站，理论上应该始终保持连接（设置为1）。\r\n   ',
  `NET_ID` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '网络配置\r\n   \r\n   和本地网络配置表关联',
  `NET_STATUS` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'RTU与系统的当前连接状态\r\n   1：正在连接\r\n   0：断开连接',
  PRIMARY KEY (`RTU_CD`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Records of wr_rtu_b_exp
-- ----------------------------

-- ----------------------------
-- Table structure for wr_rtu_mon_ext
