  `CAMERA_COND` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '摄像头状态（球机）',
  `OM_COND` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '光猫状态',
  `COMMUNICATION_TYPE` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '通讯方式，0 4G 1 有线',
  `CAMERA2_COND` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '摄像头状态（枪机）',
  `BAT_CHARGE_C` decimal(6, 2) NULL DEFAULT NULL COMMENT '蓄电池充电电流',
  `BAT_COND` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '蓄电池状态 0 正常，1欠压，2浮充，3充满，4超充',
  `BAT_TMP` decimal(5, 2) NULL DEFAULT NULL COMMENT '蓄电池温度',
  `BAT_LIFE_PER` decimal(3, 0) NULL DEFAULT NULL COMMENT '蓄电池寿命百分比',
  `BAT_CYC_NUM` decimal(6, 0) NULL DEFAULT NULL COMMENT '蓄电池循环次数',
  `BAT_REMAIN_VAL` decimal(6, 0) NULL DEFAULT NULL COMMENT '蓄电池剩余容量 单位：mAh',
  `FLOWMETER_COND` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '流量计电源状态',
  `MST` decimal(4, 1) NULL DEFAULT NULL COMMENT '箱内湿度',
  PRIMARY KEY (`TM`, `STCD`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = DYNAMIC;

