-- ----------------------------
-- Table structure for wr_sens_b
-- ----------------------------
DROP TABLE IF EXISTS `wr_sens_b`;
CREATE TABLE `wr_sens_b`  (
  `SENS_CD` varchar(13) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '传感器代码',
  `WR__RTU_CD` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT 'RTU代码',
  `WR__ORG_CD` varchar(9) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL,
  `RTU_CD` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'RTU代码',
  `ORG_CD` varchar(9) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '组织机构代码',
  `SENS_TP` varchar(2) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT '传感器类型',
  `SENS_BRAND` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '传感器品牌',
  `SENS_SN` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '传感器型号',
  `POWER` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '电源',
  `INTER_TP` char(1) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '接口方式',
  `RFID_SN` varchar(9) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT 'RFID标识码',
  `PROD_DT` datetime NULL DEFAULT NULL COMMENT '出厂日期',
  `TS` longblob NOT NULL COMMENT '时间戳',
  `NT` text CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL COMMENT '备注',
  `POINT` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NULL DEFAULT NULL COMMENT '安装位置',
  `POINT_X` decimal(10, 7) NULL DEFAULT NULL COMMENT '安装位置经度',
  `POINT_Y` decimal(10, 7) NULL DEFAULT NULL COMMENT '安装位置纬度',
  PRIMARY KEY (`SENS_CD`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8mb3 COLLATE = utf8mb3_general_ci ROW_FORMAT = DYNAMIC;

