-- ----------------------------
-- Triggers structure for table st_pstat_r
-- ----------------------------
DROP TRIGGER IF EXISTS `TRIG_ST_PSTAT_R`;
delimiter ;;
CREATE TRIGGER `TRIG_ST_PSTAT_R` AFTER INSERT ON `st_pstat_r` FOR EACH ROW BEGIN
DECLARE nidtm DATETIME;
DECLARE laccp decimal(6,1);
DECLARE drp decimal(5,1);
DECLARE llaccp decimal(6,1);
DECLARE lmaccp decimal(6,1);
DECLARE dyp decimal(5,1);
DECLARE dmp decimal(5,1);
if (NEW.STTDRCD='6')THEN
  if(right(NEW.IDTM,5) = '00:00')
  THEN
    -- 计算小时雨量
    IF(EXISTS(SELECT STCD FROM ST_PSTAT_R WHERE STCD=NEW.STCD AND STTDRCD='6' and IDTM=DATE_ADD(NEW.IDTM,INTERVAL -1 HOUR)))
    THEN
      SELECT ACCP INTO laccp from ST_PSTAT_R where STCD=NEW.STCD AND STTDRCD='6' and IDTM=DATE_ADD(NEW.IDTM,INTERVAL -1 HOUR) LIMIT 1;
      set drp=NEW.ACCP-laccp;
      if(drp<0 or drp>200)
      THEN
        set drp=0;
      END IF;
      if(right(NEW.IDTM,8) = '08:00:00' and EXISTS(SELECT STCD FROM ST_PSTAT_R WHERE STCD=NEW.STCD AND STTDRCD='6' and IDTM=DATE_ADD(NEW.IDTM,INTERVAL -1 DAY)))
      THEN
        SELECT ACCP INTO llaccp from ST_PSTAT_R where STCD=NEW.STCD AND STTDRCD='6' and IDTM=DATE_ADD(NEW.IDTM,INTERVAL -1 DAY);
        set dyp=NEW.ACCP-llaccp;
        if(dyp<0 or dyp>500)
        THEN
          SELECT SUM(DRP) INTO dyp FROM ST_PPTN_HOUR WHERE STCD=NEW.STCD AND TM >DATE_ADD(NEW.IDTM,INTERVAL -1 DAY) AND TM <= NEW.IDTM;
        END IF;
      ELSE
      END IF;
    END IF;
    -- 计算月雨量
    if(right(NEW.IDTM,11) = '01 08:00:00' and EXISTS(SELECT STCD FROM ST_PSTAT_R WHERE STCD=NEW.STCD AND STTDRCD='6' and IDTM=DATE_ADD(NEW.IDTM,INTERVAL -1 MONTH)))
    THEN
      SELECT ACCP INTO lmaccp from ST_PSTAT_R where STCD=NEW.STCD AND STTDRCD='6' and IDTM=DATE_ADD(NEW.IDTM,INTERVAL -1 MONTH) LIMIT 1;
      set dmp=NEW.ACCP-lmaccp;
      if(dmp<0 or dmp>1000)
      THEN
        SELECT SUM(DRP) INTO dmp FROM ST_PPTN_R WHERE STCD=NEW.STCD AND TM >DATE_ADD(NEW.IDTM,INTERVAL -1 MONTH) AND TM <= NEW.IDTM;
      END IF;
    END IF;
  END	IF;
END IF;
END
;;
delimiter ;

SET FOREIGN_KEY_CHECKS = 1;
