INSERT INTO `calculation_algorithm` VALUES (1, '水位计算流量', '((H-c)/a)^(1/b)', 'Math.pow((#{Z}-#{c})/#{a},1/#{b})', 3, 0, '通过水位实现流量的计算', 1, '参数a|参数b|参数c', '水位H:#{Z}');
INSERT INTO `calculation_algorithm` VALUES (2, '渗透压计算水位', 'P*0.10197+H0', '#{P}*0.10197+#{a}', 1, 0, '通过渗透压计算水位', 3, '高程H0', '渗压P:#{P}');
INSERT INTO `calculation_algorithm` VALUES (3, '频率温度计算渗透压', '(R1 – R0)G + (T1-T0) K', '(Math.pow(#{F},2)-Math.pow(#{a},2))*#{b}/1000+(#{T}-#{c})*#{d}', 4, 0, '通过频率温度计算渗透压', 3, '频率初始值|频率系数G|温度初始值|热系数K', '频率F:#{F}|温度T:#{T}');
INSERT INTO `calculation_algorithm` VALUES (4, '频率电阻计算渗透压', '(R1 – R0)G + (T1-T0) K', '(Math.pow(#{F},2)-Math.pow(#{a},2))*#{b}/1000+(1/(1.4051*Math.pow(10,-3)+2.369*Math.pow(10,-4)*Math.log(#{R})+1.019*Math.pow(10,-7)*Math.pow(Math.log(#{R}),3))-1/(1.4051*Math.pow(10,-3)+2.369*Math.pow(10,-4)*Math.log(#{c})+1.019*Math.pow(10,-7)*Math.pow(Math.log(#{c}),3)))*#{d}', 4, 0, '通过频率电阻计算渗透压', 3, '频率初始值|频率系数G|电阻初始值|热系数K', '频率F:#{F}|电阻R:#{R}');
INSERT INTO `calculation_algorithm` VALUES (5, '频率温度计算垂直位移', '(R1 – R0)G + (T1-T0) K', '(Math.pow(#{F},2)-Math.pow(#{a},2))*#{b}/1000+(#{T}-#{c})*#{d}', 4, 0, '通过频率温度计算垂直位移', 3, '频率初始值|频率系数G|温度初始值|热系数K', '频率F:#{F}|温度T:#{T}');
INSERT INTO `calculation_algorithm` VALUES (6, '频率电阻计算垂直位移', '(R1 – R0)G + (T1-T0) K', '(Math.pow(#{F},2)-Math.pow(#{a},2))*#{b}/1000+(1/(1.4051*Math.pow(10,-3)+2.369*Math.pow(10,-4)*Math.log(#{R})+1.019*Math.pow(10,-7)*Math.pow(Math.log(#{R}),3))-1/(1.4051*Math.pow(10,-3)+2.369*Math.pow(10,-4)*Math.log(#{c})+1.019*Math.pow(10,-7)*Math.pow(Math.log(#{c}),3)))*#{d}', 4, 0, '通过频率电阻计算垂直位移', 3, '频率初始值|频率系数G|电阻初始值|热系数K', '频率F:#{F}|电阻R:#{R}');
INSERT INTO `calculation_algorithm` VALUES (7, 'X轴电压电阻计算X轴位移', '0.5*G*L*(R1-R0+0.0005*(T1-T0))', '0.5*#{a}*#{b}*(#{UX}-#{c}+(1/(1.4051*Math.pow(10,-3)+2.369*Math.pow(10,-4)*Math.log(#{R})+1.019*Math.pow(10,-7)*Math.pow(Math.log(#{R}),3))-1/(1.4051*Math.pow(10,-3)+2.369*Math.pow(10,-4)*Math.log(#{d})+1.019*Math.pow(10,-7)*Math.pow(Math.log(#{d}),3)))*0.0005)', 4, 0, '通过X轴电压电阻计算X轴位移', 3, '仪器系数G|测斜仪长度L|X轴电压初始值|电阻初始值', '电压UX:#{UX}|电阻R:#{R}');
INSERT INTO `calculation_algorithm` VALUES (8, 'Y轴电压电阻计算Y轴位移', '0.5*G*L*(R1-R0+0.0005*(T1-T0))', '0.5*#{a}*#{b}*(#{UY}-#{c}+(1/(1.4051*Math.pow(10,-3)+2.369*Math.pow(10,-4)*Math.log(#{R})+1.019*Math.pow(10,-7)*Math.pow(Math.log(#{R}),3))-1/(1.4051*Math.pow(10,-3)+2.369*Math.pow(10,-4)*Math.log(#{d})+1.019*Math.pow(10,-7)*Math.pow(Math.log(#{d}),3)))*0.0005)', 4, 0, '通过Y轴电压电阻计算Y轴位移', 3, '仪器系数G|测斜仪长度L|Y轴电压初始值|电阻初始值', '电压UY:#{UY}|电阻R:#{R}');
INSERT INTO `calculation_algorithm` VALUES (9, '频率计算渗流量', 'C*((R1-R0)*G)^(5/2)', 'Math.pow((Math.pow(#{F},2)-Math.pow(#{a},2))*#{b}/1000,5/2)*#{c}', 3, 0, '通过频率计算渗流量', 3, '频率初始值|频率系数G|系数C', '频率F:#{F}');
INSERT INTO `calculation_algorithm` VALUES (10, '频率计算应变', 'G*C*(R-R0)', '(#{F}-#{a})*#{b}*#{c}', 3, 0, '通过频率计算应变', 3, '频率初始值|率定系数G|系数C', '频率F:#{F}');
